        raise ValueError("TERPSICHORE blocks must contain at least one interval.")
    if arr.shape[2] == interval_index + 1:
        return arr[:, :, interval_index]
    return arr[:, :, interval_index]


def _symmetrize_upper(block):
    """Expand a TERPSICHORE upper-triangle block to a symmetric matrix.

    Fortran ``ENERGY`` only reads the diagonal and upper triangle of every
    block and doubles the off-diagonal upper entries.  The equivalent dense
    quadratic form therefore uses ``triu(B) + triu(B).T - diag(B)`` for each
    stored block.  Applying this to the interval blocks makes the dense global
    matrices symmetric and exactly consistent with
    :func:`compute_block_energy_contributions`.
    """

    arr = np.asarray(block, dtype=float)
    upper = np.triu(arr)
    return upper + upper.T - np.diag(np.diag(arr))


def _add_quadratic(matrix, left, right, coeff):
    coeff = _symmetrize_upper(coeff)
    matrix[np.ix_(left, right)] += coeff
    if not np.array_equal(left, right):
        matrix[np.ix_(right, left)] += coeff.T

