def _symmetrize_center_nodes(center):
    """Mirror Fortran MTASKA upper-triangle center-node assembly."""

    center = np.asarray(center, dtype=float).copy()
    upper_rows, upper_cols = np.triu_indices(center.shape[0], k=1)
    center[upper_cols, upper_rows, :] = center[upper_rows, upper_cols, :]
    return center


def _symmetrize_upper(block):
    """Expand a TERPSICHORE upper-triangle block to a symmetric matrix."""

    arr = np.asarray(block, dtype=float)
    upper = np.triu(arr)
    return upper + upper.T - np.diag(np.diag(arr))


def _symmetrized_block_set(potential_blocks, kinetic_blocks):
    """Return block containers expanded to the symmetric ENERGY convention.

    TERPSICHORE block matrices store only their upper-triangle data and the
    energy routines double the upper off-diagonal entries.  PAMERA's operator
    must act on the same symmetric quadratic form as
    :func:`compute_block_energy_contributions`; otherwise the inverse
    iteration solves a different pencil than the energy interpretation.
    """

    from .blocks import TerpsichoreKineticBlocks, TerpsichorePotentialBlocks

    def expand(block):
        arr = np.asarray(block, dtype=float)
        return np.stack([_symmetrize_upper(arr[:, :, i]) for i in range(arr.shape[2])], axis=2)

    potential_fields = TerpsichorePotentialBlocks.__dataclass_fields__
    kinetic_fields = TerpsichoreKineticBlocks.__dataclass_fields__
    expanded_potential = {
        name: expand(getattr(potential_blocks, name))
        for name in potential_fields
    }
    expanded_kinetic = {}
    for name in kinetic_fields:
        value = getattr(kinetic_blocks, name)
        if value is None:
            expanded_kinetic[name] = None
        else:
            expanded_kinetic[name] = expand(value)
    return (
        TerpsichorePotentialBlocks(**expanded_potential),
        TerpsichoreKineticBlocks(**expanded_kinetic),
    )

